/* Tactile material samples from the original clay carriage concept. Embedded so canvas hit testing also works from a local file. */
(() => {
  "use strict";
  const photos = {
    hand: "",
    wool: "",
    seat: "",
    enamel: "",
    sky: "",
    chrome: "",
    canvas: ""
  };
  const materials = {};
  for (const [name, data] of Object.entries(photos)) {
    const image = new Image();
    image.onload = () => { materials[name] = image; };
    image.src = "data:image/webp;base64," + data;
  }
  window.ClaySetMaterials = materials;
})();
